//! Rust runner. Usage: runner <problem_dir> <cases.json> <iters> <warmup>
//! See tools/lc/langs.py for the contract. Prints {"cases": [{"ns", "result"}]}.
//!
//! Your solutions live in src/problems/<id>.rs.
//! src/problems/mod.rs and src/registry.rs are generated by `lc`.

mod problems;
mod registry;

use serde::de::DeserializeOwned;
use serde_json::{Value, json};
use std::hint::black_box;
use std::path::Path;
use std::time::Instant;

/// A solution's return value, converted to JSON after timing.
pub trait Out {
    fn json(&self) -> Value;
}
impl<T: serde::Serialize> Out for T {
    fn json(&self) -> Value {
        serde_json::to_value(self).expect("result is not serializable")
    }
}

/// One ready-to-run call: inputs already decoded, calling it runs only the solution.
pub type Thunk = Box<dyn FnOnce() -> Box<dyn Out>>;

/// Decode parameter `name` from a case's input (type inferred from the solution's signature).
pub fn arg<T: DeserializeOwned>(input: &Value, name: &str) -> Result<T, String> {
    let v = input.get(name).ok_or_else(|| format!("missing input {name}"))?;
    serde_json::from_value(v.clone()).map_err(|e| format!("{name}: {e}"))
}

fn run() -> Result<Value, String> {
    let args: Vec<String> = std::env::args().collect();
    let [_, problem_dir, cases_file, iters, warmup] = args.as_slice() else {
        return Err("usage: runner <problem_dir> <cases.json> <iters> <warmup>".into());
    };
    let id = Path::new(problem_dir).file_name().unwrap().to_string_lossy().to_string();
    let iters: usize = iters.parse().map_err(|_| "bad iters")?;
    let warmup: usize = warmup.parse().map_err(|_| "bad warmup")?;
    let text = std::fs::read_to_string(cases_file).map_err(|e| e.to_string())?;
    let cases: Vec<Value> = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    let mut out = Vec::new();
    for case in &cases {
        let mut times = Vec::with_capacity(iters);
        let mut result = Value::Null;
        for i in 0..warmup + iters {
            let thunk = registry::prepare(&id, &case["input"])?; // fresh copy, not timed
            let start = Instant::now();
            let r = black_box(thunk());
            let ns = start.elapsed().as_nanos();
            if i >= warmup {
                times.push(ns);
            }
            if i + 1 == warmup + iters {
                result = r.json();
            }
        }
        times.sort_unstable();
        out.push(json!({ "ns": times[times.len() / 2], "result": result }));
    }
    Ok(json!({ "cases": out }))
}

fn main() {
    match run() {
        Ok(v) => println!("{v}"),
        Err(e) => {
            eprintln!("{e}");
            std::process::exit(1);
        }
    }
}
